-- ==========================================================
-- ATHIRA CRACKERS / ADHIRA PYROTECH - SUPABASE POSTGRESQL SCHEMA
-- Complete Schema & Full Store Data Seed (154 Products, 22 Categories, 7 Orders)
-- Ready to Paste & Run in Supabase SQL Editor
-- ==========================================================

-- 1. Table: settings
CREATE TABLE IF NOT EXISTS public.settings (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  setting_key TEXT UNIQUE NOT NULL,
  setting_value TEXT,
  updated_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now())
);

-- 2. Table: categories
CREATE TABLE IF NOT EXISTS public.categories (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name TEXT NOT NULL,
  sort_order INT DEFAULT 0,
  position INT DEFAULT 0,
  created_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now())
);

-- 3. Table: products
CREATE TABLE IF NOT EXISTS public.products (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  cat_id BIGINT NOT NULL,
  name TEXT NOT NULL,
  description TEXT DEFAULT '',
  orig_price NUMERIC(10,2) NOT NULL DEFAULT 0.00,
  sale_price NUMERIC(10,2) NOT NULL DEFAULT 0.00,
  img TEXT DEFAULT '',
  video TEXT DEFAULT '',
  position INT DEFAULT 0,
  out_of_stock BOOLEAN DEFAULT FALSE,
  created_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now()),
  updated_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now())
);

-- 4. Table: banners
CREATE TABLE IF NOT EXISTS public.banners (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  img TEXT NOT NULL,
  title TEXT DEFAULT '',
  subtitle TEXT DEFAULT '',
  link TEXT DEFAULT '',
  sort_order INT DEFAULT 0,
  created_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now())
);

-- 5. Table: combos
CREATE TABLE IF NOT EXISTS public.combos (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name TEXT NOT NULL,
  items TEXT DEFAULT '',
  rate NUMERIC(10,2) DEFAULT 0.00,
  orig_price NUMERIC(10,2) DEFAULT 0.00,
  sale_price NUMERIC(10,2) DEFAULT 0.00,
  img TEXT DEFAULT '',
  video TEXT DEFAULT '',
  position INT DEFAULT 0,
  created_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now())
);

-- 6. Table: giftboxes
CREATE TABLE IF NOT EXISTS public.giftboxes (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name TEXT NOT NULL,
  items TEXT DEFAULT '',
  rate NUMERIC(10,2) DEFAULT 0.00,
  orig_price NUMERIC(10,2) DEFAULT 0.00,
  sale_price NUMERIC(10,2) DEFAULT 0.00,
  img TEXT DEFAULT '',
  video TEXT DEFAULT '',
  position INT DEFAULT 0,
  created_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now())
);

-- 7. Table: orders (Supports string order numbers e.g. ATH-20261006-3906)
CREATE TABLE IF NOT EXISTS public.orders (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  order_number TEXT DEFAULT '',
  order_type TEXT DEFAULT 'online',
  customer_name TEXT DEFAULT '',
  customer_phone TEXT DEFAULT '',
  customer_email TEXT DEFAULT '',
  customer_address TEXT DEFAULT '',
  city TEXT DEFAULT '',
  state TEXT DEFAULT 'Tamil Nadu',
  pincode TEXT DEFAULT '',
  status TEXT DEFAULT 'pending',
  items_json TEXT DEFAULT '[]',
  subtotal NUMERIC(10,2) DEFAULT 0.00,
  discount_amount NUMERIC(10,2) DEFAULT 0.00,
  total_amount NUMERIC(10,2) DEFAULT 0.00,
  payment_method TEXT DEFAULT 'COD',
  notes TEXT DEFAULT '',
  source TEXT DEFAULT 'website',
  created_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now())
);

-- Migration Helper: Ensure orders columns exist and order_number is TEXT
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_schema = 'public' AND table_name = 'orders' AND column_name = 'order_number' AND data_type != 'text'
  ) THEN
    ALTER TABLE public.orders ALTER COLUMN order_number TYPE TEXT USING order_number::TEXT;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'orders' AND column_name = 'order_type') THEN
    ALTER TABLE public.orders ADD COLUMN order_type TEXT DEFAULT 'online';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'orders' AND column_name = 'customer_email') THEN
    ALTER TABLE public.orders ADD COLUMN customer_email TEXT DEFAULT '';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'orders' AND column_name = 'state') THEN
    ALTER TABLE public.orders ADD COLUMN state TEXT DEFAULT 'Tamil Nadu';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'orders' AND column_name = 'payment_method') THEN
    ALTER TABLE public.orders ADD COLUMN payment_method TEXT DEFAULT 'COD';
  END IF;
END $$;

-- ==========================================================
-- ROW LEVEL SECURITY (RLS) POLICIES
-- ==========================================================
ALTER TABLE public.settings ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.banners ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.combos ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.giftboxes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY;

DO $$
BEGIN
  DROP POLICY IF EXISTS "Allow all for settings" ON public.settings;
  CREATE POLICY "Allow all for settings" ON public.settings FOR ALL USING (true) WITH CHECK (true);

  DROP POLICY IF EXISTS "Allow all for categories" ON public.categories;
  CREATE POLICY "Allow all for categories" ON public.categories FOR ALL USING (true) WITH CHECK (true);

  DROP POLICY IF EXISTS "Allow all for products" ON public.products;
  CREATE POLICY "Allow all for products" ON public.products FOR ALL USING (true) WITH CHECK (true);

  DROP POLICY IF EXISTS "Allow all for banners" ON public.banners;
  CREATE POLICY "Allow all for banners" ON public.banners FOR ALL USING (true) WITH CHECK (true);

  DROP POLICY IF EXISTS "Allow all for combos" ON public.combos;
  CREATE POLICY "Allow all for combos" ON public.combos FOR ALL USING (true) WITH CHECK (true);

  DROP POLICY IF EXISTS "Allow all for giftboxes" ON public.giftboxes;
  CREATE POLICY "Allow all for giftboxes" ON public.giftboxes FOR ALL USING (true) WITH CHECK (true);

  DROP POLICY IF EXISTS "Allow all for orders" ON public.orders;
  CREATE POLICY "Allow all for orders" ON public.orders FOR ALL USING (true) WITH CHECK (true);
END $$;

-- Optional: Create Storage Bucket for Media
VALUES ('media', 'media', true)
ON CONFLICT (id) DO UPDATE SET public = true;

DO $$
BEGIN
  DROP POLICY IF EXISTS "Public Media Access" ON storage.objects;
  CREATE POLICY "Public Media Access" ON storage.objects FOR ALL USING (bucket_id = 'media') WITH CHECK (bucket_id = 'media');
EXCEPTION WHEN OTHERS THEN
  NULL;
END $$;

